using System.Buffers.Binary;
using System.Runtime.InteropServices;
using System.Security.AccessControl;
using System.Security.Cryptography;
using System.Security.Principal;
using System.Text;
using DotLLM.Core.Models;

namespace DotLLM.Engine.PromptCache;

/// <summary>Private, ephemeral, checksummed files. Only names generated by this instance are removed.</summary>
internal sealed class RecurrentPrefixDiskStore : IDisposable
{
    internal const int HeaderBytes = 4096;
    private const int HeaderHashOffset = HeaderBytes - 32;
    private const ulong Magic = 0x3153504D4C4C4F44; // DOLLMPS1
    private readonly string _directory;
    private readonly long _budget;
    private readonly Dictionary<string, long> _files = new(StringComparer.Ordinal);
    private long _reserved;
    internal long Bytes => checked(_files.Values.Sum() + _reserved);

    internal sealed record FileEntry(string Path, long RawBytes, long PayloadBytes, int PrefixLength, string Identity)
    {
        internal long FileBytes => checked(HeaderBytes + PayloadBytes);
    }

    internal RecurrentPrefixDiskStore(string directory, long budget)
    {
        _budget = budget;
        string root = Path.GetFullPath(directory);
        RejectReparseAncestors(root);
        Directory.CreateDirectory(root);
        RejectReparseAncestors(root);
        _directory = Path.Combine(root, "session-" + Guid.NewGuid().ToString("N"));
        SecureDirectory(_directory);
    }

    private static void RejectReparseAncestors(string path)
    {
        for (var dir = new DirectoryInfo(path); dir is not null; dir = dir.Parent)
            if (dir.Exists && (dir.Attributes & FileAttributes.ReparsePoint) != 0)
                throw new IOException("Snapshot directory must not traverse symbolic links or reparse points.");
    }

    private static void SecureDirectory(string path)
    {
        if (OperatingSystem.IsWindows())
        {
            var user = WindowsIdentity.GetCurrent().User ?? throw new IOException("Cannot determine snapshot directory owner.");
            var security = new DirectorySecurity();
            security.SetOwner(user);
            security.SetAccessRuleProtection(isProtected: true, preserveInheritance: false);
            security.AddAccessRule(new FileSystemAccessRule(user, FileSystemRights.FullControl,
                InheritanceFlags.ContainerInherit | InheritanceFlags.ObjectInherit, PropagationFlags.None, AccessControlType.Allow));
            new DirectoryInfo(path).Create(security);
        }
        else
        {
            Directory.CreateDirectory(path, UnixFileMode.UserRead | UnixFileMode.UserWrite | UnixFileMode.UserExecute);
        }
        RejectReparseAncestors(path);
    }

    // Measure without materializing the payload or writing to disk. Immutable snapshots serialize twice so budget
    // reservation is exact before touching disk, including metadata and the in-progress temporary file.
    internal long Measure(IPersistableRecurrentPrefixSnapshot snapshot)
    {
        long limit = Math.Min(_budget - HeaderBytes, checked(snapshot.ByteCount + 65536));
        if (limit <= 0) throw new IOException("Snapshot exceeds disk budget.");
        using var count = new PayloadWriter(null, limit);
        snapshot.WriteTo(count);
        return count.Length;
    }

    internal FileEntry Write(IPersistableRecurrentPrefixSnapshot snapshot, int[] tokens, long payloadBytes)
    {
        long total = checked(HeaderBytes + payloadBytes);
        if (payloadBytes <= 0 || total > _budget - Bytes) throw new IOException("Snapshot disk budget exhausted.");
        string stem = Path.Combine(_directory, Guid.NewGuid().ToString("N"));
        string temporary = stem + ".tmp", final = stem + ".snapshot";
        _reserved = total;
        try
        {
            var options = new FileStreamOptions
            {
                Mode = FileMode.CreateNew, Access = FileAccess.ReadWrite, Share = FileShare.None,
                Options = FileOptions.Asynchronous | FileOptions.WriteThrough, BufferSize = 65536,
            };
            if (!OperatingSystem.IsWindows()) options.UnixCreateMode = UnixFileMode.UserRead | UnixFileMode.UserWrite;
            using (var stream = new FileStream(temporary, options))
            {
                byte[] header = new byte[HeaderBytes];
                stream.Write(header);
                using var writer = new PayloadWriter(stream, payloadBytes);
                snapshot.WriteTo(writer);
                if (writer.Length != payloadBytes) throw new InvalidDataException("Snapshot serialization length changed.");
                BinaryPrimitives.WriteUInt64LittleEndian(header, Magic);
                BinaryPrimitives.WriteInt32LittleEndian(header.AsSpan(8), 1);
                BinaryPrimitives.WriteInt64LittleEndian(header.AsSpan(16), snapshot.ByteCount);
                BinaryPrimitives.WriteInt64LittleEndian(header.AsSpan(24), payloadBytes);
                BinaryPrimitives.WriteInt32LittleEndian(header.AsSpan(32), snapshot.PrefixLength);
                int identityLength = Encoding.UTF8.GetByteCount(snapshot.Identity);
                if (identityLength > HeaderHashOffset - 104) throw new InvalidDataException("Snapshot identity is too long.");
                BinaryPrimitives.WriteInt32LittleEndian(header.AsSpan(36), identityLength);
                TokenHash(tokens).CopyTo(header, 40);
                writer.FinishHash().CopyTo(header, 72);
                Encoding.UTF8.GetBytes(snapshot.Identity, header.AsSpan(104, identityLength));
                SHA256.HashData(header.AsSpan(0, HeaderHashOffset), header.AsSpan(HeaderHashOffset));
                stream.Position = 0; stream.Write(header); stream.Flush(flushToDisk: true);
            }
            File.Move(temporary, final, overwrite: false);
            _files.Add(final, total);
            return new(final, snapshot.ByteCount, payloadBytes, snapshot.PrefixLength, snapshot.Identity);
        }
        finally
        {
            try { File.Delete(temporary); }
            catch (IOException) { TrackLeftover(temporary); }
            catch (UnauthorizedAccessException) { TrackLeftover(temporary); }
            _reserved = 0;
        }
    }

    private void TrackLeftover(string path)
    {
        try { if (File.Exists(path)) _files[path] = new FileInfo(path).Length; }
        catch (IOException) { _files[path] = _reserved; }
        catch (UnauthorizedAccessException) { _files[path] = _reserved; }
    }

    internal FileStream OpenVerified(FileEntry entry, int[] tokens, string identity)
    {
        if (!_files.ContainsKey(entry.Path) || (File.GetAttributes(entry.Path) & FileAttributes.ReparsePoint) != 0)
            throw new InvalidDataException("Snapshot file is not owned by this cache.");
        var stream = new FileStream(entry.Path, FileMode.Open, FileAccess.Read, FileShare.Read | FileShare.Delete,
            65536, FileOptions.Asynchronous | FileOptions.SequentialScan);
        try
        {
            if (stream.Length != entry.FileBytes) throw new InvalidDataException("Snapshot file length mismatch.");
            byte[] header = new byte[HeaderBytes]; stream.ReadExactly(header);
            Span<byte> hash = stackalloc byte[32];
            SHA256.HashData(header.AsSpan(0, HeaderHashOffset), hash);
            int identityLength = BinaryPrimitives.ReadInt32LittleEndian(header.AsSpan(36));
            if (!CryptographicOperations.FixedTimeEquals(hash, header.AsSpan(HeaderHashOffset))
                || BinaryPrimitives.ReadUInt64LittleEndian(header) != Magic
                || BinaryPrimitives.ReadInt32LittleEndian(header.AsSpan(8)) != 1
                || BinaryPrimitives.ReadInt64LittleEndian(header.AsSpan(16)) != entry.RawBytes
                || BinaryPrimitives.ReadInt64LittleEndian(header.AsSpan(24)) != entry.PayloadBytes
                || BinaryPrimitives.ReadInt32LittleEndian(header.AsSpan(32)) != tokens.Length
                || tokens.Length != entry.PrefixLength || identity != entry.Identity
                || identityLength < 0 || identityLength > HeaderHashOffset - 104
                || Encoding.UTF8.GetString(header.AsSpan(104, identityLength)) != identity
                || !CryptographicOperations.FixedTimeEquals(TokenHash(tokens), header.AsSpan(40, 32)))
                throw new InvalidDataException("Snapshot metadata mismatch.");
            SHA256.HashData(stream, hash);
            if (!CryptographicOperations.FixedTimeEquals(hash, header.AsSpan(72, 32)))
                throw new InvalidDataException("Snapshot checksum mismatch.");
            stream.Position = HeaderBytes;
            return stream;
        }
        catch { stream.Dispose(); throw; }
    }

    internal void Delete(FileEntry entry) => DeleteOwned(entry.Path);
    private void DeleteOwned(string path)
    {
        if (!_files.ContainsKey(path)) return;
        try { File.Delete(path); _files.Remove(path); }
        catch (IOException) { /* Retain accounting for a file the OS could not remove. */ }
        catch (UnauthorizedAccessException) { }
    }
    internal void Clear() { foreach (string path in _files.Keys.ToArray()) DeleteOwned(path); }
    public void Dispose()
    {
        Clear();
        try { Directory.Delete(_directory, recursive: false); }
        catch (IOException) { }
        catch (UnauthorizedAccessException) { }
    }

    private static byte[] TokenHash(int[] tokens)
        => SHA256.HashData(MemoryMarshal.AsBytes(tokens.AsSpan()));

    private sealed class PayloadWriter(Stream? target, long limit) : Stream
    {
        private readonly IncrementalHash? _hash = target is null ? null : IncrementalHash.CreateHash(HashAlgorithmName.SHA256);
        private long _length;
        public override long Length => _length;
        public override bool CanRead => false;
        public override bool CanSeek => false;
        public override bool CanWrite => true;
        public override long Position { get => _length; set => throw new NotSupportedException(); }
        public override void Write(byte[] buffer, int offset, int count) => Write(buffer.AsSpan(offset, count));
        public override void Write(ReadOnlySpan<byte> buffer)
        {
            if (buffer.Length > limit - _length) throw new IOException("Snapshot serialized payload exceeds its bound.");
            target?.Write(buffer); _hash?.AppendData(buffer); _length += buffer.Length;
        }
        public override ValueTask WriteAsync(ReadOnlyMemory<byte> buffer, CancellationToken cancellationToken = default)
        {
            cancellationToken.ThrowIfCancellationRequested();
            if (buffer.Length > limit - _length) throw new IOException("Snapshot serialized payload exceeds its bound.");
            if (target is null) { _length += buffer.Length; return ValueTask.CompletedTask; }
            return WritePayloadAsync(buffer, cancellationToken);
        }
        private async ValueTask WritePayloadAsync(ReadOnlyMemory<byte> buffer, CancellationToken cancellationToken)
        {
            // Preserve pointer-backed pinned memory through FileStream's overlapped I/O path.
            await target!.WriteAsync(buffer, cancellationToken).ConfigureAwait(false);
            _hash!.AppendData(buffer.Span); _length += buffer.Length;
        }
        public override Task WriteAsync(byte[] buffer, int offset, int count, CancellationToken cancellationToken)
            => WriteAsync(buffer.AsMemory(offset, count), cancellationToken).AsTask();
        internal byte[] FinishHash() => _hash!.GetHashAndReset();
        public override void Flush() => target?.Flush();
        public override int Read(byte[] buffer, int offset, int count) => throw new NotSupportedException();
        public override long Seek(long offset, SeekOrigin origin) => throw new NotSupportedException();
        public override void SetLength(long value) => throw new NotSupportedException();
        protected override void Dispose(bool disposing) { if (disposing) _hash?.Dispose(); base.Dispose(disposing); }
    }
}
